import { createRoot } from 'react-dom/client';
import cronstrue from 'cronstrue';
import { Activity, ArrowDown, ArrowRight, ArrowUp, BookOpen, Check, ChevronDown, CircleHelp, Clock3, Film, KeyRound, ListFilter, Loader2, LogOut, Menu, MoreHorizontal, Play, Plus, Radio, Search, Settings2, ShieldCheck, SlidersHorizontal, Trash2, Tv, Users, WandSparkles, X } from 'lucide-react';
