  return <span className="run-bubbles">{failed>0&&<span className="run-bubble failed" title={`${failed} failed or blocked`}>{failed} failed</span>}<span className={`run-bubble ${count?preview?'planned':'changed':'none'}`} title={preview?`${count} planned changes`:`${count} verified changes`}>{count} {preview?'planned':'changed'}</span></span>;
