      <div className="form-grid">{fields.map(f=><label key={f.key}>{f.label.toUpperCase()}<input type={f.secret?'password':'text'} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})} placeholder={f.placeholder}/></label>)}</div>
      {error&&<p className="error">{error}</p>}
